begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();v uuid:=gen_random_uuid();d uuid:=gen_random_uuid();s uuid:=gen_random_uuid();k uuid:=gen_random_uuid();event jsonb;c public.device_challenges;expected jsonb;amr jsonb;claims jsonb;
 e jsonb:='{"crypto_version":"leqvor-v5","algorithm":"AES-256-GCM","aad_version":1,"nonce":"AAAAAAAAAAAAAAAA","ciphertext":"AAAAAAAAAAAAAAAAAAAAAA=="}';
 pub jsonb:=jsonb_build_object('kty','EC','crv','P-256','x',repeat('A',43),'y',repeat('B',43));
begin
 insert into auth.users(id) values(a),(b);
 insert into public.vaults(id,owner_id,wrapped_vmk_password,wrapped_vmk_recovery,kdf_salt,kdf_parameters,recovery_salt,crypto_version,recovery_verified_at) values(v,a,e,e,'fixture','{}','fixture','leqvor-v5',now());
 insert into public.review_signing_keys(id,owner_id,vault_id,public_key,encrypted_metadata,encrypted_payload,wrapped_dek,crypto_version) values(k,a,v,pub,e,e,e,'leqvor-v5');
 event:=jsonb_build_object('id',gen_random_uuid(),'owner_id',a,'sequence',1,'event_type','DEVICE_ENROLLED','severity','INFO','device_id',d,'previous_hash',null,'created_at',clock_timestamp(),'signing_key_id',k,'event_hash',repeat('A',43)||'=','signature',repeat('A',86)||'==');
 amr:=jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from now())::bigint));
 claims:=jsonb_build_object('role','authenticated','session_id',s,'aal','aal1','amr',amr);
 if has_function_privilege('authenticated','public.complete_verified_v5_device(uuid,uuid,jsonb,text,jsonb,jsonb,jsonb)','execute') or has_function_privilege('anon','public.begin_v5_device_challenge(uuid,uuid,text,jsonb)','execute') then raise exception 'FAIL exposed verification';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',claims::text,true);execute 'set local role authenticated';
 begin insert into public.vault_devices(id,owner_id,vault_id,public_key) values(d,a,v,pub);raise exception 'FAIL direct enrollment';exception when insufficient_privilege then null;end;
 c:=public.begin_v5_device_challenge(v,d,'enroll',pub);expected:=to_jsonb(c);
 if c.session_id<>s or c.owner_id<>a or c.consumed_at is not null or length(c.nonce)<>64 then raise exception 'FAIL challenge binding';end if;
 begin perform public.begin_v5_device_challenge(v,d,'enroll',pub||'{"d":"PRIVATE"}');raise exception 'FAIL private material';exception when invalid_parameter_value then null;end;
 execute 'reset role';perform set_config('request.jwt.claim.sub',b::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.device_challenges) then raise exception 'FAIL foreign challenge read';end if;
 begin perform public.begin_v5_device_challenge(v,d,'enroll',pub);raise exception 'FAIL foreign enrollment';exception when insufficient_privilege then null;end;
 execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 begin perform public.complete_verified_v5_device(a,gen_random_uuid(),amr,'aal1',expected,event,pub);raise exception 'FAIL different session';exception when sqlstate 'PT409' then null;end;
 begin perform public.complete_verified_v5_device(a,s,'[]','aal1',expected,event,pub);raise exception 'FAIL stale auth';exception when insufficient_privilege then null;end;
 begin perform public.complete_verified_v5_device(b,s,amr,'aal1',expected,event,pub);raise exception 'FAIL different owner';exception when sqlstate 'PT409' then null;end;
 begin perform public.complete_verified_v5_device(a,s,amr,'aal1',expected||'{"nonce":"CHANGED"}',event,pub);raise exception 'FAIL altered challenge';exception when sqlstate 'PT409' then null;end;
 execute 'reset role';insert into auth.mfa_factors(id,user_id,status) values(gen_random_uuid(),a,'verified');execute 'set local role service_role';
 begin perform public.complete_verified_v5_device(a,s,amr,'aal1',expected,event,pub);raise exception 'FAIL MFA bypass';exception when insufficient_privilege then null;end;
 begin perform public.complete_verified_v5_device(a,s,amr,'aal2',expected,event||'{"sequence":2}',pub);raise exception 'FAIL stale history';exception when sqlstate 'PT409' then null;end;
 execute 'reset role';
 if exists(select 1 from public.vault_devices where id=d) or exists(select 1 from public.device_challenges where id=c.id and consumed_at is not null) then raise exception 'FAIL enrollment rollback';end if;
 execute 'set local role service_role';
 perform public.complete_verified_v5_device(a,s,amr,'aal2',expected,event,pub);
 begin perform public.complete_verified_v5_device(a,s,amr,'aal2',expected,event,pub);raise exception 'FAIL replay';exception when sqlstate 'PT409' then null;end;
 execute 'reset role';perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',(claims||'{"aal":"aal2"}')::text,true);execute 'set local role authenticated';
 if (select count(*) from public.vault_devices)<>1 then raise exception 'FAIL owner registry';end if;
 begin update public.vault_devices set revoked_at=null;raise exception 'FAIL direct mutation';exception when insufficient_privilege then null;end;
 event:=event||jsonb_build_object('id',gen_random_uuid(),'sequence',2,'event_type','DEVICE_PROOF_VERIFIED','previous_hash',repeat('A',43)||'=','event_hash',repeat('B',43)||'=');
 c:=public.begin_v5_device_challenge(v,d,'verify',pub);expected:=to_jsonb(c);
 execute 'reset role';update public.device_challenges set expires_at=clock_timestamp()-interval '1 second' where id=c.id;select to_jsonb(x) into expected from public.device_challenges x where id=c.id;perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 begin perform public.complete_verified_v5_device(a,s,amr,'aal2',expected,event,pub);raise exception 'FAIL expired challenge';exception when sqlstate 'PT409' then null;end;
 execute 'reset role';perform set_config('request.jwt.claims',(claims||'{"aal":"aal2"}')::text,true);execute 'set local role authenticated';
 c:=public.begin_v5_device_challenge(v,d,'verify',pub);expected:=to_jsonb(c);
 execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 begin perform public.revoke_verified_v5_device(a,amr,'aal2',d,event||'{"event_type":"DEVICE_REVOKED","sequence":99}',pub);raise exception 'FAIL revocation history conflict';exception when sqlstate 'PT409' then null;end;
 execute 'reset role';
 if exists(select 1 from public.vault_devices where id=d and revoked_at is not null) or not exists(select 1 from public.device_challenges where id=c.id) then raise exception 'FAIL revocation rollback';end if;
 execute 'set local role service_role';
 perform public.revoke_verified_v5_device(a,amr,'aal2',d,event||'{"event_type":"DEVICE_REVOKED"}',pub);
 execute 'reset role';perform set_config('request.jwt.claims',(claims||'{"aal":"aal2"}')::text,true);execute 'set local role authenticated';
 begin perform public.begin_v5_device_challenge(v,d,'verify',pub);raise exception 'FAIL revoked proof';exception when insufficient_privilege then null;end;
 execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 begin perform public.complete_verified_v5_device(a,s,amr,'aal2',expected,event,pub);raise exception 'FAIL in-flight revoked challenge';exception when sqlstate 'PT409' then null;end;
 execute 'reset role';perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',claims::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.vault_devices) then raise exception 'FAIL foreign registry';end if;
 begin perform public.revoke_verified_v5_device(b,amr,'aal1',d,event,pub);raise exception 'FAIL foreign revoke';exception when insufficient_privilege then null;end;
 execute 'reset role';delete from auth.users where id=a;
 if exists(select 1 from public.vault_devices where owner_id=a) or exists(select 1 from public.device_challenges where owner_id=a) then raise exception 'FAIL deletion cleanup';end if;
end $$;
rollback;
